Translate the following GNU C++0x code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++0x code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdio>
using namespace std;

using vi = vector<int>;

void input_int(int& x) {
    scanf("%d", &x);
}

void input_int_pair(int& a, int& b) {
    scanf("%d %d", &a, &b);
}

void input_int_triple(int& a, int& b, int& c) {
    scanf("%d %d %d", &a, &b, &c);
}

void input_int_quad(int& a, int& b, int& c, int& d) {
    scanf("%d %d %d %d", &a, &b, &c, &d);
}

void input_line_int(int& x) {
    scanf("%d\n", &x);
}

void input_line_int_pair(int& a, int& b) {
    scanf("%d %d\n", &a, &b);
}

void input_line_int_triple(int& a, int& b, int& c) {
    scanf("%d %d %d\n", &a, &b, &c);
}

void input_line_int_quad(int& a, int& b, int& c, int& d) {
    scanf("%d %d %d %d\n", &a, &b, &c, &d);
}

void output_int(int x) {
    printf("%d\n", x);
}

void output_int(int a, int b) {
    printf("%d %d\n", a, b);
}

void output_int(int a, int b, int c) {
    printf("%d %d %d\n", a, b, c);
}

void output_int(int a, int b, int c, int d) {
    printf("%d %d %d %d\n", a, b, c, d);
}

void output_int_inline(int x) {
    printf("%d", x);
}

void output_int_inline(int a, int b) {
    printf("%d %d", a, b);
}

void output_int_inline(int a, int b, int c) {
    printf("%d %d %d", a, b, c);
}

void output_int_inline(int a, int b, int c, int d) {
    printf("%d %d %d %d", a, b, c, d);
}

void input_vector(vi& v, int n) {
    v.resize(n);
    for (int i = 0; i < n; ++i) {
        input_int(v[i]);
    }
}

void output_vector(const vi& v) {
    for (size_t i = 0; i < v.size(); ++i) {
        printf("%d%c", v[i], (i == v.size() - 1) ? '\n' : ' ');
    }
}

void execute() {
    int n, t;
    vi arr;
    input_int(n);
    input_vector(arr, n);
    sort(arr.begin(), arr.end());

    int i = 0, j = 0, max_span = 0;
    input_int(t);

    while (j < n) {
        while (j < n && arr[j] - arr[i] <= t) {
            ++j;
        }
        max_span = max(max_span, j - i);
        ++i;
    }

    output_int(max_span);
}

int main() {
    execute();
    return 0;
}
